"""Install CI-only potion checks into the dedicated-server test build."""
import json
from pathlib import Path

source = Path("src/main/java/com/simibubi/create/infrastructure/fabric/PotionRecipeProbe.java")
source.write_text("package com.simibubi.create.infrastructure.fabric;\n\nimport com.simibubi.create.AllDataComponents;\nimport com.simibubi.create.content.fluids.potion.PotionFluid;\nimport com.simibubi.create.content.fluids.potion.PotionFluidHandler;\nimport com.simibubi.create.content.fluids.potion.PotionMixingRecipes;\nimport com.simibubi.create.content.fluids.transfer.GenericItemEmptying;\nimport com.simibubi.create.content.fluids.transfer.GenericItemFilling;\nimport com.simibubi.create.infrastructure.fabric.transfer.fluid.FluidStack;\nimport net.fabricmc.api.ModInitializer;\nimport net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;\nimport net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants;\nimport net.minecraft.core.component.DataComponents;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.Items;\nimport net.minecraft.world.item.alchemy.PotionContents;\nimport net.minecraft.world.item.alchemy.Potions;\n\npublic class PotionRecipeProbe implements ModInitializer {\n    private static void check(boolean condition, String message) {\n        if (!condition) throw new IllegalStateException(\"POTION_PROBE: \" + message);\n    }\n\n    @Override\n    public void onInitialize() {\n        ServerLifecycleEvents.SERVER_STARTED.register(server -> {\n            var level = server.overworld();\n            int roundTrips = 0;\n            for (var potion : java.util.List.of(Potions.WATER, Potions.AWKWARD, Potions.HEALING, Potions.POISON)) {\n                for (var type : PotionFluid.BottleType.values()) {\n                    ItemStack original = PotionContents.createItemStack(PotionFluidHandler.itemFromBottleType(type).asItem(), potion);\n                    var simulated = GenericItemEmptying.emptyItem(level, original, true);\n                    check(original.getCount() == 1, \"simulation consumed a potion\");\n                    check(simulated.getFirst().getAmount() == FluidConstants.BOTTLE, \"drain amount is not one bottle\");\n                    var drained = GenericItemEmptying.emptyItem(level, original.copy(), false);\n                    check(drained.getSecond().is(Items.GLASS_BOTTLE), \"drain did not return glass\");\n                    FluidStack fluid = drained.getFirst();\n                    long required = GenericItemFilling.getRequiredAmountForItem(level, drained.getSecond(), fluid);\n                    check(required == fluid.getAmount(), \"drain/refill loses or duplicates fluid\");\n                    ItemStack restored = GenericItemFilling.fillItem(level, required, drained.getSecond(), fluid);\n                    check(ItemStack.isSameItemSameComponents(original, restored), \"potion or bottle type changed on refill\");\n                    check(fluid.isEmpty(), \"refill did not consume exactly one bottle\");\n                    roundTrips++;\n                }\n            }\n\n            var recipes = PotionMixingRecipes.createRecipes(level);\n            check(!recipes.isEmpty(), \"no runtime brewing recipes generated\");\n            int componentChecks = 0;\n            for (var holder : recipes) {\n                var recipe = holder.value();\n                check(recipe.getFluidIngredients().size() == 1 && recipe.getFluidResults().size() == 1, \"unexpected brewing fluid slots\");\n                var input = recipe.getFluidIngredients().getFirst();\n                var output = recipe.getFluidResults().getFirst();\n                check(input.getRequiredAmount() == FluidConstants.BUCKET, \"brewing input is not one bucket\");\n                check(output.getAmount() == input.getRequiredAmount(), \"brewing changes fluid quantity\");\n                FluidStack accepted = input.getMatchingFluidStacks().getFirst();\n                check(input.test(accepted), \"brewing rejects its own input\");\n                var contents = accepted.get(DataComponents.POTION_CONTENTS);\n                if (contents != null) {\n                    FluidStack wrongPotion = accepted.copy();\n                    wrongPotion.set(DataComponents.POTION_CONTENTS, new PotionContents(contents.is(Potions.POISON) ? Potions.HEALING : Potions.POISON));\n                    check(!input.test(wrongPotion), \"brewing accepts a different potion\");\n                    FluidStack wrongBottle = accepted.copy();\n                    var type = accepted.getOrDefault(AllDataComponents.POTION_FLUID_BOTTLE_TYPE, PotionFluid.BottleType.REGULAR);\n                    wrongBottle.set(AllDataComponents.POTION_FLUID_BOTTLE_TYPE,\n                        type == PotionFluid.BottleType.REGULAR ? PotionFluid.BottleType.SPLASH : PotionFluid.BottleType.REGULAR);\n                    check(!input.test(wrongBottle), \"brewing accepts a different bottle type\");\n                    componentChecks++;\n                }\n            }\n            check(componentChecks > 0, \"no potion-specific brewing ingredients checked\");\n            System.out.println(\"POTION_PROBE passed: \" + roundTrips + \" bottle round trips, \" + recipes.size()\n                + \" brewing quantities, \" + componentChecks + \" potion/bottle identity checks\");\n        });\n    }\n}\n")
manifest = Path("src/main/resources/fabric.mod.json")
value = json.loads(manifest.read_text())
value["entrypoints"]["main"].append("com.simibubi.create.infrastructure.fabric.PotionRecipeProbe")
manifest.write_text(json.dumps(value, indent=2))
